.card:hover { transform: translateY(-3px); box-shadow: var(--shadow); }
.tag { display: inline-block; padding: .2rem .55rem; border-radius: 999px; font-size: .73rem; background: #eef5f7; color: var(--teal); font-weight: 600; margin-bottom: .55rem; }

