.cap-grid { display: grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap: 1rem; }
.insight-list { display: grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap: 1rem; }

.carousel { position: relative; overflow: hidden; border: 1px solid var(--gray-100); border-radius: var(--radius); }
